steps.command:
/bin/zsh -lc ".venv/bin/python - <<'PY'
import ast, pathlib
for path in sorted(pathlib.Path('billing').glob('*.py')):
    tree=ast.parse(path.read_text())
    for node in tree.body:
        funcs=[(node,None)] if isinstance(node,ast.FunctionDef) else [(n,node.name) for n in node.body if isinstance(n,ast.FunctionDef)] if isinstance(node,ast.ClassDef) else []
        for fn,cls in funcs:
            if fn.returns is None: print(f'UNANNOTATED {path.stem}.{cls+\".\" if cls else \"\"}{fn.name}')
PY"
